  void (*n2m[4])(const double *fquad, double *fmodal, long linc2);
} qn2m_list[] = {
  {NULL, NULL, NULL, NULL}, // No 0D basis functions
  {NULL, quad_to_modal_1d_ser_p1, quad_to_modal_1d_ser_p2, NULL},
