  void (*n2m[4])(const double *fmodal, double *fquad, long linc2);
} m2qn_list[] = {
  {NULL, NULL, NULL, NULL}, // No 0D basis functions
  {NULL, modal_to_quad_1d_ser_p1, modal_to_quad_1d_ser_p2, NULL},
